import os
import sys
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"
KEY_PATH = "/app/ssl/server.key"
PEM_PATH = "/app/ssl/server.pem"


def run_openssl(args):
    result = subprocess.run(["openssl"] + args, capture_output=True, text=True)
    if result.returncode != 0:
        print(f"OpenSSL error: {result.stderr.strip()}")
        return None
    return result.stdout.strip()


def main():
    all_ok = True

    # Check files exist
    for path, label in [(CERT_PATH, "Certificate"), (KEY_PATH, "Private key"), (PEM_PATH, "PEM file")]:
        if not os.path.exists(path):
            print(f"Error: {label} not found at {path}")
            all_ok = False

    if not all_ok:
        sys.exit(1)

    # Get and print subject / Common Name
    subject = run_openssl(["x509", "-in", CERT_PATH, "-noout", "-subject"])
    if subject:
        print(f"Subject: {subject}")
        # Extract Common Name from subject string
        parts = subject.split("=", 1)[1] if "=" in subject else subject
        cn = None
        for segment in parts.split(","):
            segment = segment.strip()
            if segment.startswith("CN "):
                cn = segment.split("= ")[1] if "= " in segment else segment[3:].strip()
                break
        if cn:
            print(f"Common Name: {cn}")

    # Get expiration date in YYYY-MM-DD format
    enddate = run_openssl(["x509", "-in", CERT_PATH, "-noout", "-enddate"])
    if enddate:
        date_str = enddate.split("=", 1)[1]
        dt = datetime.strptime(date_str, "%b %d %H:%M:%S %Y %Z")
        yyyy_mm_dd = dt.strftime("%Y-%m-%d")
        print(f"Expiration Date: {yyyy_mm_dd}")

    # Get fingerprint
    fingerprint = run_openssl(["x509", "-in", CERT_PATH, "-noout", "-fingerprint", "-sha256"])
    if fingerprint:
        print(f"Fingerprint: {fingerprint}")

    # Verify key is valid RSA
    key_check = run_openssl(["rsa", "-in", KEY_PATH, "-check", "-noout"])
    if key_check:
        print(f"Key check: {key_check}")

    # Verify certificate matches private key
    cert_modulus = run_openssl(["x509", "-in", CERT_PATH, "-noout", "-modulus"])
    key_modulus = run_openssl(["rsa", "-in", KEY_PATH, "-noout", "-modulus"])
    if cert_modulus and key_modulus:
        if cert_modulus == key_modulus:
            print("Certificate and private key match")
        else:
            print("Error: Certificate and private key do not match")
            all_ok = False

    if all_ok:
        print("\nCertificate verification successful")
    else:
        print("\nCertificate verification failed")
        sys.exit(1)


if __name__ == "__main__":
    main()
